using System;
using System.Text;
using UnityEngine;

public class SimulateImageResponse : MonoBehaviour
{
    
    // 
    [ContextMenu("Simulate Image Prompt")]
    public void SimulateImageFromServer()
    {
        string json =
            "{\"type\": \"image_result\", \"content\": \"\"}";

        byte[] jsonBytes = Encoding.UTF8.GetBytes(json);
        byte[] fakePacket = new byte[1 + jsonBytes.Length];
        fakePacket[0] = 0x01;
        Buffer.BlockCopy(jsonBytes, 0, fakePacket, 1, jsonBytes.Length);

        // i changed signature of ShowImage
        // GetComponent<ImageHandler>().ShowImage(fakePacket);
    }
}
